style:
#facturx-warning {
    margin: -7px;

    .facturx-warning-banner {
        display: flex;
        gap: var(--padding-md);
        align-items: flex-start;
        padding: var(--padding-md) var(--padding-lg);
        background: var(--yellow-50, #fffbeb);
        border: 1px solid var(--yellow-300, #fcd34d);
        border-left: 4px solid var(--yellow-500, #f59e0b);
        border-radius: var(--border-radius-lg);
        color: var(--yellow-900, #78350f);
    }

    .warning-icon {
        flex-shrink: 0;
        padding-top: 2px;
        color: var(--yellow-600, #d97706);
        line-height: 0;
    }

    .warning-content {
        p {
            margin: 0 0 var(--padding-xs);
            font-size: var(--text-base);
            line-height: 1.6;

            &:last-child { margin-bottom: 0; }
        }
    }

    .warning-title {
        font-weight: 600;
        font-size: var(--text-md) !important;
        margin-bottom: var(--padding-sm) !important;
    }
}
